30	const PROCESSING_FEE = 5;
31	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
32	
33	const BASE_PREMIUMS: Record<string, number> = {
34	  sword: 100,
35	  amulet: 60,
36	  staff: 80,
37	  potion: 40,
38	  rune: 25,
39	  moonstone: 25,
40	};
41	
42	const CURSE_SURCHARGE_RATE = 0.5;
43	const HIGH_ENCHANTMENT_THRESHOLD = 5;
44	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
45	
46	const BLOCK_SIZE = 3;
47	const BLOCK_BASE_PREMIUM = 60;
48	
49	const itemBasePremium = (item: Item): number => BASE_PREMIUMS[item.type];
50	
51	const countByType = (items: Item[]): Map<string, number> => {
52	  const counts = new Map<string, number>();
53	  for (const item of items) {
54	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
55	  }
56	  return counts;
57	};
58	
59	// A block is exactly BLOCK_SIZE alike items, charged as one unit.
60	const formsBlock = (count: number): boolean => count === BLOCK_SIZE;
61	
62	const groupBasePremium = (type: string, count: number): number =>
63	  formsBlock(count) ? BLOCK_BASE_PREMIUM : count * BASE_PREMIUMS[type];
64	
65	const policyBasePremium = (items: Item[]): number =>
66	  [...countByType(items)].reduce(
67	    (total, [type, count]) => total + groupBasePremium(type, count),
68	    0,
69	  );
70	
71	// The MHPCO rounds in its own favour: premiums up, payouts down.
72	const roundUpInMHPCOsFavour = (amount: number): number => Math.ceil(amount);
73	
74	// Item-scoped modifiers apply to the affected item's own base premium.
75	const itemSurcharge = (item: Item): number => {
76	  const base = itemBasePremium(item);
77	  const curse = item.cursed ? base * CURSE_SURCHARGE_RATE : 0;
78	  const enchantment =
79	    (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD
80	      ? base * HIGH_ENCHANTMENT_SURCHARGE_RATE
81	      : 0;
82	
83	  return curse + enchantment;
84	};
85	
86	const itemSurcharges = (items: Item[]): number =>
87	  items.reduce((total, item) => total + itemSurcharge(item), 0);
88	
89	const quote = (step: Step): QuoteResult => {
90	  const policyBase = policyBasePremium(step.items);
91	  const firstInsuranceSurcharge = policyBase * FIRST_INSURANCE_SURCHARGE_RATE;
92	  const modifiedPremium =
93	    policyBase + itemSurcharges(step.items) + firstInsuranceSurcharge;
94	
95	  return {
96	    premium: roundUpInMHPCOsFavour(modifiedPremium + PROCESSING_FEE),
97	  };
98	};
99	
100	export const runScenario = (scenario: Scenario): ScenarioResult => ({
101	  results: scenario.steps.map(quote),
102	});
